The transformed HJB equation (\ref{eq:HJB transformed}) simplifies to
\begin{equation} 
-\partial_t v_t^\ast = b \cdot \nabla_x v_t^\ast + \frac{1}{2}  \Sigma : D_x^2 v_t^\ast  - c v_t^\ast 
\end{equation}
for the special case $G = \sigma$ and $R = I$ and 
(\ref{eq:HJB transformed}) becomes linear in $v_t^\ast$. This well-known fact has been exploited in the numerical work of \cite{MO22}. Furthermore, the transformed HJB equation arising from the further simplification $c(x)\equiv 0$  leads to the standard backward Kolmogorov equation \cite{Pavliotis2016}.

\label{lemma1}
Given the forward evolution equation (\ref{eq:Liouville_forward}) and the HJB equation
(\ref{eq:HJB transformed}), the probability density defined by (\ref{eq:product}) satisfies the reverse time evolution
equation
\begin{equation} \label{eq:Liouville_backward}
-\partial_t \tilde \pi_t = -\nabla_x \cdot \left(\tilde \pi_t \tilde b_t \right)
-  \tilde \pi_t \left(c - \alpha_t +  \frac{1}{2}\|\sigma^{\rm T} 
\nabla_x \log v_t^\ast \|^2 - \frac{1}{2} \|R G^{\rm T} \nabla_x \log v^\ast_t\|^2_R - \zeta_t\right)
\end{equation}
with terminal condition $\tilde \pi_T = Z_T^{-1}\exp(-f) \bar \pi_T$, where $\zeta_t$ is an appropriate normalization constant.

Since (\ref{eq:tilde b}) and 
\begin{equation}
\nabla_x \cdot (\Sigma \nabla_x v_t^\ast) = \nabla_x v_t^\ast \cdot (\nabla_x \cdot \Sigma) + \Sigma : D_x^2 v_t^\ast,
\end{equation}
and assuming that (\ref{eq:product}) holds, 
it follows that
\begin{subequations}
\begin{align}
-\nabla_x \cdot (\tilde \pi_t \tilde b_t) 
&= \nabla_x \cdot \left(\tilde \pi_t \left( \bar b_t + \frac{1}{2} \Sigma \nabla_x \log v_t^\ast \right)\right)\\
&= \frac{v_t^\ast}{Z_t} \nabla_x  \cdot (\bar \pi_t \bar b_t ) + \frac{\bar \pi_t}{Z_t} (\Sigma \nabla_x v_t^\ast) \cdot \bar b_t
+ \frac{1}{2Z_t} \nabla_x \cdot (\bar \pi_t \Sigma \nabla_x v_t^\ast)\\


&= \frac{v_t^\ast}{Z_t} \nabla_x  \cdot (\bar \pi_t \bar b_t ) + \frac{\bar \pi_t}{Z_t} \left( \nabla_x v_t^\ast \cdot \left(
 b -\frac{1}{2} \nabla_x \cdot \Sigma   \right)
+  \frac{1}{2}  \nabla_x \cdot ( \Sigma \nabla_x v_t^\ast) \right)\\
&= \frac{v_t^\ast}{Z_t}  \nabla_x \cdot \left( \bar \pi_t \bar b_t \right)
+ \frac{\bar \pi_t}{Z_t} \left( b \cdot \nabla_x  v_t^\ast + \frac{1}{2} \Sigma : D_x^2  v_t^\ast \right).
\end{align}
\end{subequations}
Hence it holds indeed that
\begin{equation}
\partial_t \tilde \pi_t = \frac{v_t^\ast}{Z_t} \partial_t \bar \pi_t + \frac{\bar \pi_t}{Z_t} \partial_t v_t^\ast - \frac{\tilde \pi}{Z_t} \frac{{\rm d}Z_t}{{\rm d}t}
\end{equation}
for the partial time derivatives given by (\ref{eq:Liouville_backward}), (\ref{eq:Liouville_forward}), and (\ref{eq:HJB transformed}), respectively.
Furthermore, $\tilde \pi_T = v_T^\ast \bar \pi_T/Z_T$ at final time and, hence, (\ref{eq:product}) holds for all times $t\in (0,T]$.

The two diffusion processes defined by 
(\ref{eq:FB mean field}) satisfy $\bar X_t \sim \bar \pi_t$ and $\tilde X_t \sim \tilde \pi_t$, respectively. 
Given $\tilde \pi_t$ and $\bar \pi_t$, the optimal control law $u_t^\ast(x)$ is provided by
\begin{equation}
u_t^\ast(x) = R G(x)^{\rm T} \left( \nabla_x \log \tilde \pi_t(x) - \nabla_x \log \bar \pi_t(x) \right).
\end{equation}
